import{_ as a,a as t}from"./chunks/launcher_new_connection.CyzeJolZ.js";import{_ as s,c as i,o as n,ag as r}from"./chunks/framework.Ci10AEOF.js";const o="/docs-website/assets/gs_web_browser_step_1.CFnx0zSQ.png",d="/docs-website/assets/welcome_dialog.B-7CHxga.png",h="/docs-website/assets/gs_oie_dashboard.CeaKf2LY.png",k=JSON.parse('{"title":"Accessing the Administrator","description":"Reaching a running OIE server, choosing between the web and desktop administrators, and logging in","frontmatter":{"title":"Accessing the Administrator","description":"Reaching a running OIE server, choosing between the web and desktop administrators, and logging in"},"headers":[],"relativePath":"engine/accessing_the_administrator.md","filePath":"engine/accessing_the_administrator.md","lastUpdated":1793057853000}'),l={name:"engine/accessing_the_administrator.md"};function c(p,e,g,m,u,b){return n(),i("div",null,e[0]||(e[0]=[r('<h1 id="accessing-the-administrator" tabindex="-1">Accessing the Administrator <a class="header-anchor" href="#accessing-the-administrator" aria-label="Permalink to &quot;Accessing the Administrator&quot;">​</a></h1><p>To verify that the OIE server is available, open a browser and enter the URL from the startup output, <code>https://&lt;host&gt;:8443/</code>. See <a href="./server_process_management.html">Server Process Management</a> if it is not up yet.</p><p>After accepting the self-signed certificate in your browser, you will see this page:</p><p><img src="'+o+'" alt="Open Integration Engine Server home Page indicating the service is available with launcher target url and button to explore the Client API"></p><p>From here there are two ways to administer the engine: a browser, or the desktop Administrator.</p><h2 id="web-administrator" tabindex="-1">Web Administrator <a class="header-anchor" href="#web-administrator" aria-label="Permalink to &quot;Web Administrator&quot;">​</a></h2><p>The Web Administrator is a browser-based administrator, developed separately from the engine as <a href="https://github.com/gibson9583/oie-web-client" target="_blank" rel="noreferrer">oie-web-client</a>. It works read/write against the same REST API as the desktop client, covering channel editing, deployment, and the message browser. No launcher is involved.</p><p>It runs in one of three ways: as a standalone Node.js app, as a Docker container, or inside the engine&#39;s own web server. For the last, install the <a href="https://github.com/gibson9583/oie-web-support-plugin" target="_blank" rel="noreferrer">Web Support</a> community extension by Chris Gibson as you would any other extension (see the <a href="./plugins.html">plugin guide</a>), restart the engine, and open <code>https://&lt;host&gt;:8443/oie-webadmin/</code>. See <a href="./web_administrator.html">Web Administrator</a> for what it covers and which engine versions it supports.</p><h2 id="desktop-administrator" tabindex="-1">Desktop Administrator <a class="header-anchor" href="#desktop-administrator" aria-label="Permalink to &quot;Desktop Administrator&quot;">​</a></h2><p>The desktop Administrator is a Java application and needs a launcher to start it. Copy the Administrator Launcher URL from the page above, then use Launcher, below. See <a href="/docs-website/launchers/">Launchers</a> for more about it, and <a href="./desktop_administrator.html">Desktop Administrator</a> for a tour of the client.</p><h3 id="launcher" tabindex="-1">Launcher <a class="header-anchor" href="#launcher" aria-label="Permalink to &quot;Launcher&quot;">​</a></h3><p><a href="https://github.com/diridium-com/launcher/releases" target="_blank" rel="noreferrer">Launcher</a> is an open-source Administrator launcher for Open Integration Engine, built on Tauri and released under MPL-2.0. It is a fork of Ballista.</p><p><img src="'+a+'" alt="Launcher&#39;s main window listing two connections, one online and one unreachable"></p><p>Add a connection with the engine&#39;s address, <code>https://&lt;host&gt;:8443</code>, and the Java home of a JavaFX-enabled JDK, then double-click the connection or click its play button to start the Administrator.</p><p><img src="'+t+`" alt="Launcher&#39;s New Connection dialog with the name, address, Java home, username and password filled in"></p><h2 id="initial-admin-password" tabindex="-1">Initial admin password <a class="header-anchor" href="#initial-admin-password" aria-label="Permalink to &quot;Initial admin password&quot;">​</a></h2><p>A new database has one user, <code>admin</code>. Unless <code>server.initialadminpassword</code> in <code>conf/mirth.properties</code> is set before the server first starts, the server generates a random password for it and writes it once, at WARN level, to the console and to <code>logs/mirth.log</code>:</p><div class="language-log vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">log</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">WARN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ... </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">com.mirth.connect.server.Mirth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">********************************************************************************</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">************   Initial admin password is Aa1!xxxxxxxxxxxxxxxxxxxx   ************</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">********************************************************************************</span></span></code></pre></div><p>The generated password is 24 characters long and starts with <code>Aa1!</code>. <code>server.initialadminpassword</code> is read only when the database is created.</p><p>A database that already exists, after an upgrade or a migration from Mirth Connect, keeps its users and their passwords.</p><p>The CLI&#39;s shipped <code>conf/mirth-cli-config.properties</code> contains <code>user=admin</code> and <code>password=admin</code>. Put the real password there, or pass it with <code>-p</code>. See <a href="./command_line_interface.html#configuration">Command Line Interface</a>.</p><h2 id="logging-in" tabindex="-1">Logging in <a class="header-anchor" href="#logging-in" aria-label="Permalink to &quot;Logging in&quot;">​</a></h2><p>Enter your credentials and click <code>Login</code> when the login screen appears. After a brief loading screen, you will see the OIE dashboard.</p><h3 id="first-login" tabindex="-1">First login <a class="header-anchor" href="#first-login" aria-label="Permalink to &quot;First login&quot;">​</a></h3><p>In the desktop Administrator, every user&#39;s first login opens a dialog titled <strong>Welcome to Open Integration Engine</strong> before the dashboard.</p><p><img src="`+d+'" alt="The Welcome to Open Integration Engine dialog, with New Password and Confirm New Password marked required and Finish disabled"></p><p>Enter a password in <code>New Password</code> and <code>Confirm New Password</code>, then click <code>Finish</code>. <code>Finish</code> stays disabled until both are filled in, and the server refuses a password that does not meet the <a href="./user_management.html#password-policy">password policy</a>, which with the shipped settings means at least 15 characters. The other fields are optional. Closing the dialog logs you out.</p><p><img src="'+h+'" alt="Application ready to use at the Dashboard screen showing no deployed channels and the server startup messages in the log section"></p><div class="warning custom-block"><p class="custom-block-title">Every account is an administrator</p><p>All users are administrators by default, with privilege to write and execute channel scripts on the server. Grant access only to users who should be able to author and execute scripts, or install an RBAC plugin to create low-privileged roles.</p><p><a href="https://github.com/diridium-com/role-based-access-control" target="_blank" rel="noreferrer">Role Based Access Control</a> is a community extension that replaces the default authorization controller with roles and per-channel grants, and it works in both administrators.</p></div>',29)]))}const _=s(l,[["render",c]]);export{k as __pageData,_ as default};
